'use strict';

// Turning the report into a file.
//
// The report says which paths are noise; this writes that into `.aiignore`.
// It only ever appends: an existing line — a comment, a hand-written rule, a
// rule with different spacing — is left exactly as it is. Running twice adds
// nothing the second time.
//
// It does not claim the score will drop afterwards: the scan is a static
// heuristic over file names and sizes and does not read `.aiignore` yet.

const fs = require('fs');

const HEADER = [
  "# Files that waste an AI coding agent's context.",
  '# Generated by ai-context-doctor. Review before committing.'
];

function isRuleLine(line) {
  const trimmed = String(line).trim();
  return trimmed !== '' && !trimmed.startsWith('#');
}

function parseRules(text) {
  const rules = new Set();

  for (const line of text.split(/\r?\n/)) {
    if (isRuleLine(line)) rules.add(line.trim());
  }

  return rules;
}

function planAiignore({ existing, suggested }) {
  const known = existing === null ? new Set() : parseRules(existing);
  const existingRules = known.size;
  const added = [];

  for (const item of suggested) {
    const rule = String(item).trim();
    if (!isRuleLine(rule) || known.has(rule)) continue;
    known.add(rule);
    added.push(rule);
  }

  return { added, created: existing === null, existingRules };
}

function renderAiignore({ existing, added, created }) {
  const rules = added.join('\n');

  if (created) return `${HEADER.join('\n')}\n\n${rules}\n`;

  // Keep everything the user already had, byte for byte, and only drop the
  // trailing whitespace before appending so the file ends in one newline.
  const body = existing.replace(/\s+$/, '');
  return body === '' ? `${rules}\n` : `${body}\n${rules}\n`;
}

function fail(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

function writeAiignore(aiignorePath, suggested, options = {}) {
  const { dryRun = false } = options;
  let existing = null;

  // `existsSync` follows the link, so a *dangling* symlink reads as "no file
  // here" and `writeFileSync` would then create whatever it points at. lstat
  // is the only call that answers the question we are actually asking.
  let stats = null;
  try {
    stats = fs.lstatSync(aiignorePath);
  } catch {
    stats = null;
  }
  if (stats !== null) {
    // Refuse anything that could write somewhere other than the scanned repo.
    if (stats.isSymbolicLink()) {
      throw fail(
        'is-a-symlink',
        `${aiignorePath} is a symbolic link; refusing to write through it.`
      );
    }
    if (!stats.isFile()) {
      throw fail('not-a-file', `${aiignorePath} exists but is not a regular file.`);
    }
    existing = fs.readFileSync(aiignorePath, 'utf8');
  }

  const plan = planAiignore({ existing, suggested });
  const { added, created } = plan;
  const result = {
    path: aiignorePath,
    added,
    created,
    existingRules: plan.existingRules,
    written: false,
    dryRun
  };

  if (added.length === 0 || dryRun) return result;

  fs.writeFileSync(aiignorePath, renderAiignore({ existing, added, created }), 'utf8');
  result.written = true;

  return result;
}

/**
 * Split an `.aiignore` line into the pattern and whether it unblocks.
 *
 * `!` is the only control character the matcher understands. A line that is
 * blank, a comment, or just a bare `!` is not a rule at all, so callers skip it
 * exactly as gitignore does.
 *
 * @param {string} rule
 * @returns {{ pattern: string, negated: boolean, rule: string } | null}
 */
function parseRule(rule) {
  const trimmed = String(rule).trim();
  if (trimmed === '' || trimmed.startsWith('#')) return null;

  const negated = trimmed.startsWith('!');
  const pattern = (negated ? trimmed.slice(1) : trimmed).trim();
  if (pattern === '' || pattern.startsWith('#')) return null;

  return { pattern, negated, rule: trimmed };
}

/**
 * Match one pattern against a workspace-relative path.
 *
 * Deliberately a small subset of gitignore: `#` comments, a trailing `/` for
 * directories, `*` within a segment, `**` across segments, and — the part that
 * matters most for a one-line rule — a bare `dist/` matching anything under a
 * directory of that name at any depth. The leading `!` is handled by
 * `decideAiignore`, because it changes what the match *means*, not what it
 * matches.
 *
 * @param {string} pattern
 * @param {string} relativePath
 * @returns {boolean}
 */
function matchesPattern(pattern, relativePath) {
  const directoryOnly = pattern.endsWith('/');
  const body = (directoryOnly ? pattern.slice(0, -1) : pattern).replace(/^\/+/, '');
  if (body === '') return false;

  const regex = body
    .replace(/[.+^${}()|[\]\\]/g, '\\$&')
    .replace(/\*\*/g, '\u0000')
    .replace(/\*/g, '[^/]*')
    .replace(/\u0000/g, '.*');

  if (body.includes('/')) {
    return new RegExp(`^${regex}(/.*)?$`).test(relativePath);
  }

  const segments = relativePath.split('/');
  const matcher = new RegExp(`^${regex}$`);
  if (matcher.test(segments[segments.length - 1])) return true;
  // `dist/` or `dist` also covers everything below a directory of that name.
  return segments.slice(0, -1).some((segment) => matcher.test(segment));
}

/**
 * Decide what the ordered rules say about one path, including whether the last
 * line merely allowed it or actively released an earlier block.
 *
 * Ignore files are read like gitignore: every line is tried in order and the
 * **last matching line wins**. A leading `!` makes that line an exception, so
 * `*.md` followed by `!README.md` blocks other Markdown files but keeps the
 * README. A rule in any other position only matters until a later rule matches;
 * putting a broad rule back below a negation blocks the file again.
 *
 * `released` separates "a `!` line undid an earlier matching rule" from "a `!`
 * line matched a path nothing had blocked". Both leave the path allowed, but
 * only the first one changed the verdict, so `--explain` should name it.
 *
 * An exception only cancels a matching *rule*. The strength (file-size and
 * noise-category cutoffs) is applied after the rules and is not overridden by
 * `!`.
 *
 * Rules may contain patterns the matcher does not implement. Those simply never
 * match; a malformed line never throws and never breaks the caller's read path.
 *
 * @param {Iterable<string>} rules
 * @param {string} relativePath
 * @returns {{ blocked: boolean, rule: string | null, released: boolean }}
 */
function evaluateAiignore(rules, relativePath) {
  if (rules === null || rules === undefined) {
    return { blocked: false, rule: null, released: false };
  }

  const normalized = String(relativePath).split('\\').join('/');
  let decision = { blocked: false, rule: null, released: false };

  for (const rawRule of rules) {
    const parsed = parseRule(rawRule);
    if (parsed === null) continue;

    try {
      if (!matchesPattern(parsed.pattern, normalized)) continue;
    } catch {
      // A malformed pattern is just an unmatched rule, not a hard failure.
      continue;
    }

    // Last match wins: either a new block with this line, or a `!` line that
    // releases what an earlier rule would have blocked.
    const wasBlocked = decision.blocked === true;
    decision = {
      blocked: parsed.negated !== true,
      rule: parsed.rule,
      released: parsed.negated === true && wasBlocked
    };
  }

  return decision;
}

/**
 * Decide what the ordered rules say about one path.
 *
 * Kept as the two-field API existing callers use; `evaluateAiignore` carries
 * the extra `released` flag that `--explain` needs.
 *
 * @param {Iterable<string>} rules
 * @param {string} relativePath
 * @returns {{ blocked: boolean, rule: string | null }}
 */
function decideAiignore(rules, relativePath) {
  const { blocked, rule } = evaluateAiignore(rules, relativePath);
  return { blocked, rule };
}

/**
 * Return the rule that refuses this path, or undefined.
 *
 * Kept as the string/undefined API existing callers use; `decideAiignore`
 * carries the extra information that a negation matched.
 *
 * @param {Iterable<string>} rules
 * @param {string} relativePath
 * @returns {string | undefined}
 */
function matchesAiignore(rules, relativePath) {
  const decision = decideAiignore(rules, relativePath);
  return decision.blocked ? decision.rule : undefined;
}

module.exports = {
  HEADER,
  parseRules,
  evaluateAiignore,
  decideAiignore,
  matchesAiignore,
  planAiignore,
  renderAiignore,
  writeAiignore
};
